import type { ServerSoftwareType } from "./catalog";

// Settings each server software keeps in its own config files, shown on
// the Loader tab. Every entry names a key the software itself writes:
// paths and defaults were read from files generated by real servers
// (Paper 26.3 build 159, NeoForge 26.3.0.57-beta and 21.1.256, Forge 66.0.9 /
// 52.1.0 / 47.4.10 / 14.23.5.2859), and Paper's descriptions follow
// docs.papermc.io. A setting is shown only when its file exists and holds
// the key, so a version that lacks a key never gets it written.

export type LoaderFileFormat = "yaml" | "toml" | "forge-cfg";

export interface LoaderFile {
    id: string;
    format: LoaderFileFormat;
    /** the file name the UI groups settings under */
    label: string;
    /**
     * Where the software reads this file, relative to the server folder,
     * most specific first. `world` is server.properties' level-name.
     */
    locations(world: string): string[];
}

export interface LoaderSetting {
    id: string;
    file: string;
    /**
     * yaml: the key path. toml: [section, key], section "" for top level.
     * forge-cfg: [category, key] with the type prefix (B:/I:/D:) left off.
     */
    path: string[];
    title: string;
    description: string;
    control: "toggle" | "number" | "select";
    options?: { value: string; label: string }[];
    min?: number;
    max?: number;
    /** numbers may have a fractional part */
    decimal?: boolean;
    /** shown with the setting: it can damage worlds or break gameplay rules */
    warning?: string;
}

export interface LoaderSettingsSchema {
    files: LoaderFile[];
    settings: LoaderSetting[];
}

export interface LoaderSettingsInfo {
    schema: LoaderSettingsSchema | null;
    /** what the tab says when there is nothing to edit */
    emptyMessage: string;
}

const CRASH_GUARD_WARNING =
    "The software's own warning: this could break everything, use sparingly. It hides the crash instead of fixing the mod.";

