// ─── NeoForge / Forge ─────────────────────────────────────────────────

// keys the two share; Forge nests them under [server], NeoForge keeps them top level
function forgeFamilyServerSettings(file: string, section: string, prefix: string): LoaderSetting[] {
    const at = (key: string) => [section, key];
    return [
        {
            id: `${prefix}.remove-erroring-block-entities`,
            file,
            path: at("removeErroringBlockEntities"),
            title: "Remove crashing block entities",
            description: "Remove a block entity that throws an error while ticking instead of crashing the server.",
            control: "toggle",
            warning: CRASH_GUARD_WARNING,
        },
        {
            id: `${prefix}.remove-erroring-entities`,
            file,
            path: at("removeErroringEntities"),
            title: "Remove crashing entities",
            description: "Remove an entity that throws an error while ticking instead of crashing the server.",
            control: "toggle",
            warning: CRASH_GUARD_WARNING,
        },
        {
            id: `${prefix}.full-bounding-box-ladders`,
            file,
            path: at("fullBoundingBoxLadders"),
            title: "Full bounding box ladders",
            description: "Check an entity's whole collision box for ladders instead of only the block it is in. Changes climbing from vanilla.",
            control: "toggle",
        },
        {
            id: `${prefix}.advertise-to-lan`,
            file,
            path: at("advertiseDedicatedServerToLan"),
            title: "Show on local network",
            description: "Advertise the server to players on the same network so it appears in their multiplayer list.",
            control: "toggle",
        },
    ];
}

