export const LOADER_SETTINGS: Readonly<Record<ServerSoftwareType, LoaderSettingsInfo>> = {
    vanilla: {
        schema: null,
        emptyMessage: "Vanilla has no loader. Its settings are on the Options and Advanced tabs.",
    },
    paper: { schema: { files: PAPER_FILES, settings: PAPER_SETTINGS }, emptyMessage: "" },
    fabric: {
        schema: null,
        // fabric-server-launcher.properties holds only the server jar path,
        // which Paperboard manages; everything else is a launch flag
        emptyMessage: "Fabric's loader has no server settings of its own. Mods keep theirs in the config folder.",
    },
    neoforge: { schema: NEOFORGE, emptyMessage: "" },
    forge: { schema: FORGE, emptyMessage: "" },
};

export function loaderSetting(software: ServerSoftwareType, id: unknown): LoaderSetting | null {
    return LOADER_SETTINGS[software].schema?.settings.find((setting) => setting.id === id) ?? null;
}

/**
 * Validates a value for a setting and returns its canonical string, or
 * throws. The one check every write passes, at the service.
 */
export function normalizeLoaderValue(setting: LoaderSetting, raw: unknown): string {
    const value = String(raw ?? "").trim();
    switch (setting.control) {
        case "toggle":
            if (value !== "true" && value !== "false") {
                throw new Error(`${setting.title} must be true or false`);
            }
            return value;
        case "select":
            if (!setting.options?.some((option) => option.value === value)) {
                throw new Error(`${setting.title} must be one of ${setting.options?.map((o) => o.value).join(", ")}`);
            }
            return value;
        case "number": {
            const pattern = setting.decimal ? /^-?\d+(\.\d+)?$/ : /^-?\d+$/;
            if (!pattern.test(value)) {
                throw new Error(`${setting.title} must be ${setting.decimal ? "a number" : "a whole number"}`);
            }
            const num = Number(value);
            if ((setting.min !== undefined && num < setting.min) || (setting.max !== undefined && num > setting.max)) {
                throw new Error(`${setting.title} must be between ${setting.min} and ${setting.max}`);
            }
            return String(num);
        }
    }
}
